import{_ as r,o as n,c as t,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/lehrkraefte/kontextmenue-lehrkraefte.png",p=JSON.parse('{"title":"Aktionen für markierte Lehrkräfte ausführen","description":"","frontmatter":{"title":"Aktionen für markierte Lehrkräfte ausführen","source_pageid":1549,"source_revision":6401},"headers":[],"relativePath":"schild3/lehrkraefte/kontextmenue-lehrkraefte.md","filePath":"schild3/lehrkraefte/kontextmenue-lehrkraefte.md"}'),s={name:"schild3/lehrkraefte/kontextmenue-lehrkraefte.md"};function l(h,e,k,o,f,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="aktionen-fur-markierte-lehrkrafte-ausfuhren" tabindex="-1">Aktionen für markierte Lehrkräfte ausführen <a class="header-anchor" href="#aktionen-fur-markierte-lehrkrafte-ausfuhren" aria-label="Permalink to &quot;Aktionen für markierte Lehrkräfte ausführen&quot;">​</a></h1><p>Markieren Sie eine oder mehrere Lehrkräfte und öffnen Sie mit der rechten Maustaste die gemeinsamen Aktionen, etwa E-Mail-Versand und Auswahlaktionen.</p><p><a href="/bilder/lehrkraefte/kontextmenue-lehrkraefte.png"><img src="'+a+'" alt="Kontextmenü der Lehrkräfte" loading="lazy"></a></p><p><em>Kontextmenü der Lehrkräfte</em></p><p><strong>Kontextmenü der Lehrkräfte</strong></p><p>Sie können eine oder mehrere Lehrkräfte markieren und dann mit der rechten Maustaste auf die Lehrkräfte klicken. Sie gelangen so in das Kontextmenü der Lehrkräfte, wo sie verschiedene Optionen zur Auswahl haben.</p><p><strong>Alle auswählen</strong> Markieren Sie alle Lehrkräfte mit Hilfe dieses Menüpunktes.</p><p><strong>Auswahl aufheben</strong> Heben Sie über diesen Menüpunkt alle Markierungen auf.</p><p><strong>E-Mail an markierte Lehrkräfte senden (dienstliche Adresse)</strong> Senden Sie unkompliziert eine E-Mail an die dienstliche E-Mail-Adresse der markierten Lehrkräfte.</p><p><strong>E-Mail an markierte Lehrkräfte senden (Private Adresse)</strong> Senden Sie unkompliziert eine E-Mail an die private E-Mail-Adresse der markierten Lehrkräfte.</p><p><strong>Einwilligung zu Lernplattformen für markierte Lehrkräfte eingeben</strong> Setzen Sie über diesen Menüpunkt Einwilligungen zu Lernplattformen für alle markierten Lehrkräfte.</p><p><strong>Einwilligung für markierte Lehrkräfte eingeben</strong> Setzen Sie über diesen Menüpunkt DSGVO-Einwilligungen für alle markierten Lehrkräfte.</p><p><strong>Aktuelle Daten kopieren / Kopierte Daten übertragen</strong> Kopieren Sie die Daten einer einzelnen Lehrkraft und übertragen Sie diese zu einer anderen Lehrkraft.</p><p><strong>Unterricht für markierte Lehrkraft anzeigen</strong> Lassen Sie sich alle Unterrichte anzeigen, in denen die Lehrkraft im aktuellen Schuljahr eingesetzt ist.</p><p><strong>Eintrag in die Wiedervorlageliste hinzufügen</strong> Lassen Sie sich über die Wiedervorlageliste daran erinnern, bei der ausgewählten Lehrkraft eine Maßnahme vorzunehmen.</p><p><strong>Zu allgemeiner Personengruppe hinzufügen</strong> Fügen Sie die markierten Lehrkräfte zu einer allgemeinen Personengruppe hinzu.</p><p><strong>Daten aus vorherigem Abschnitt übernehmen</strong> Übernehmen Sie zeitabhängige Daten aus dem vorherigen Abschnitt in den aktuellen Abschnitt</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Kontextmen%C3%BC_(Lehrkr%C3%A4fte)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6401.</p>',19)])])}const g=r(s,[["render",l]]);export{p as __pageData,g as default};
